module div_16bit (
    input wire [15:0] A,
    input wire [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg, b_reg;
reg [15:0] quotient, remainder;

always @(*) begin
    a_reg <= A;
    b_reg <= B;
end

always @(*) begin
    quotient = 0;
    remainder = 0;
    for (integer i = 15; i >= 0; i = i - 1) begin
        remainder = {remainder[14:0], a_reg[i]};
        if (remainder >= b_reg) begin
            remainder = remainder - b_reg;
            quotient[i] = 1;
        end else begin
            quotient[i] = 0;
        end
    end
    result = quotient;
    odd = remainder;
end

endmodule
